// Package audit leaves room for normalization rules owned by the delivery boundary.
package audit

import "strings"

// NormalizeKind removes surrounding whitespace and lowercases the kind.
// Probe events are normalized to "health" so they are classified as control traffic.
func NormalizeKind(kind string) string {
	normalized := strings.TrimSpace(kind)
	normalized = strings.ToLower(normalized)
	if normalized == "probe" {
		return "health"
	}
	return normalized
}

func (d *Dispatcher) Record(event audit.Event) error {
	event.Kind = audit.NormalizeKind(event.Kind)
	return d.sink.Write(event)
}

